program='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    row_seps = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    col_seps = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]
    if row_seps:
        axis, seps, n = 0, row_seps, h
    elif col_seps:
        axis, seps, n = 1, col_seps, w
    else:
        return [row[:] for row in grid]
    spans=[]; start=0
    for s in seps:
        if s > start: spans.append((start,s))
        start=s+1
    if start<n: spans.append((start,n))
    if not spans: return [row[:] for row in grid]
    lengths=[b-a for a,b in spans]
    period=Counter(lengths).most_common(1)[0][0]
    out=[row[:] for row in grid]
    cross=w if axis==0 else h
    for local in range(period):
        for x in range(cross):
            value=None
            for a,b in spans:
                if local < b-a:
                    i=a+local
                    v=grid[i][x] if axis==0 else grid[x][i]
                    if v != bg:
                        value=v; break
            if value is not None:
                for a,b in spans:
                    if local < b-a:
                        i=a+local
                        if axis==0: out[i][x]=value
                        else: out[x][i]=value
    return out
'''
